    "content": "近日有市民反映，上海地铁人民广场站一处灯箱广告画面存在错误，画面中多个人物手部出现重影。对此，9月23日16时许，澎湃新闻记者实地走访该地铁站看到，上述灯箱原本存在瑕疵的广告画面已被替换，目前画面中的人物手部正常。 网友拍摄的照片显示，广告画面上的人物手部出现重影。图片来自网络 当日，澎湃新闻记者从上海地铁方面了解到，该灯箱广告位于人民广场站15号口附近，广告画面上的瑕疵系广告制作单位出图环节疏漏，产生拖影问题。工作人员在站内巡检过程中自行发现该广告异常，已于9月19日完成问题画面的下刊、替换工作，换刊时对相关照片…"
