    "author": "",
    "description": "36氪获悉，芯原股份公告，公司执行副总裁、定制芯片平台事业部总经理汪志伟计划自2026年10月23日至2027年1月22日，通过集中竞价方式减持公司股份不超过3.1万股，占公司总股本的0.0059%，减持原因为自身资金需求。本次减持不设价格区间。以公告披露前最近一个交易日（9月22日）的收盘价208.03元/股测算，本次拟减持股份对应的市值上限约为644.89万元。",
    "content": "36氪获悉，芯原股份公告，公司执行副总裁、定制芯片平台事业部总经理汪志伟计划自2026年10月23日至2027年1月22日，通过集中竞价方式减持公司股份不超过3.1万股，占公司总股本的0.0059%，减持原因为自身资金需求。本次减持不设价格区间。以公告披露前最近一个交易日（9月22日）的收盘价208.03元/股测算，本次拟减持股份对应的市值上限约为644.89万元。"
