    "content": "据最新消息，韩国前短道速滑国家队选手金建宇在社交平台否认其讣告是由本人发布。 此前，其个人社交账号曾发布讣告，称“我们谨此通知各位，金建宇先生于2026年9月23日逝世”。消息迅速扩散，令滑冰界、体育圈及国内外粉丝震动。 韩国前短道速滑国家队选手金建宇 网上另有传言称，讣告发出后，有自称金建宇熟人的人在社交媒体发文称“建宇没事，相关报道不实”，该帖随后被删除。 同一天下午，金建宇的社交媒体账号发表长文写道：“首先，此次事件给许多人带来困惑和担忧，我深表歉意。”文中还表示：“问题帖发出时，我已无法正常登录该账号，并不…"
