    "title": "湖南裕能：对西班牙项目增加投资至16.5亿元",
    "link": "https://36kr.com/newsflashes/3995803795230601?f=rss",
    "pub_date": "2026-09-23 18:00:39",
    "author": "",
    "description": "36氪获悉，湖南裕能公告，公司于2026年9月23日召开第二届董事会第二十五次会议，审议通过《关于对西班牙项目增加投资的议案》，同意将西班牙项目建设规模提升至年产7万吨锂电池正极材料，投资总额调整为折合人民币约16.50亿元，并授权管理层办理项目投资规模调整涉及的各类具体事宜。",
