    "content": "周三A股市场出现了整固态势。 其中，游资热钱收缩交易规模，“华”字辈题材股、传媒股大幅走低，使得短线人气有所受挫。不过，PCB板块、纺织板块、地产板块、CRO板块仍然保持着相对活跃的态势，主要股指虽然有所疲软，但空头仍保持着相对克制的状态。 美元指数走强抽离非美资产流动性 在以往，国际油价下跌，往往意味着通胀压力减缓，贵金属价格走高。相对应的是，国际油价上涨，贵金属走低。但在周三亚洲交易时段，全球资本市场出现了一个较为奇怪的走势，那就是国际油价虽然乏力，但国际金价仍然大幅调整，国际银价的跌幅更是一度超过2%。 之所…"
