    "description": "今天从中国国际信息通信展览会上了解到，“十五五”时期，我国将把握新一代通信网络建设的战略机遇，适度超前、系统推进新一代通信网建设。工业和信息化部副部长余晓晖表示，要坚持应用牵引、适度超前、系统推进新一代通信网建设，推进宽带网络向双万兆演进，推进低轨卫星互联网系统建设，统筹优化国际海陆网络布局，推动算力设施扩容提质，强化算网协同和算力互联，更好支撑一体化算力网建设。（央视新闻）",
