    "content": "中秋将至，酥香爆汁的鲜肉月饼，你吃过吗？9月22日，在第48届世界技能大赛新闻中心“匠艺现场秀”活动现场，真老大房鲜肉月饼制作技艺展演吸引不少观众驻足围观。2020年，该项技艺被列入第七批上海市黄浦区非物质文化遗产代表性项目名录。 据悉，真老大房始创于1851年，距今已有175年历史，是上海知名的中华老字号。在鲜肉月饼制作工艺上，真老大房坚持手工制作，采用传统配方，现做现售，热炉供应。 新鲜出炉的鲜肉月饼，外皮层次分明、酥松爽口，内馅肉质弹嫩、鲜美多汁、清爽不腻。酥香外皮与鲜润内馅相得益彰，呈现丰富立体的口感。让我…"
