    "content": "在山东烟台海阳市，有一个“仰望星空”的港口——东方航天港，这是目前国内唯一的商业航天海上发射母港。在这里，造火箭、发卫星、用数据，形成一条巨大的商业航天产业链。 依托烟台优越的地理位置和港口条件，当地打造了航天海上发射母港、火箭研发制造中心、卫星载荷研发制造中心、海上发射平台研发制造中心和卫星数据应用开发中心，形成了“天上有星、陆上有箭、海上有船、空中有网”的完整商业航天产业链。 截至今年8月，东方航天港已成功保障27次海上火箭发射任务，累计将166颗卫星送入预定轨道。当地正把液体火箭研发制造、发射回收、数据应用和…"
