    "description": "北京时间9月24日晚间，中国队将在重庆龙兴专业足球场迎来本次国际比赛日首场和马尔代夫的热身赛，23日傍晚，国足主帅邵佳一和球员刘殿座一起出席赛前新闻发布会，邵佳一首先感谢了比赛举办方，“重庆给我们提供了很好的条件，场地条件也很棒，希望这四场比赛能给重庆球迷和全国球迷奉献精彩的比赛。” 对于本期集训选择多名年轻球员，邵佳一表示，“我们在武汉12号开始集训，差不多一周时间，针对这四场比赛有一个准备期，相信所有球员都做好了准备。第一场比赛，希…",
    "content": "北京时间9月24日晚间，中国队将在重庆龙兴专业足球场迎来本次国际比赛日首场和马尔代夫的热身赛，23日傍晚，国足主帅邵佳一和球员刘殿座一起出席赛前新闻发布会，邵佳一首先感谢了比赛举办方，“重庆给我们提供了很好的条件，场地条件也很棒，希望这四场比赛能给重庆球迷和全国球迷奉献精彩的比赛。” 对于本期集训选择多名年轻球员，邵佳一表示，“我们在武汉12号开始集训，差不多一周时间，针对这四场比赛有一个准备期，相信所有球员都做好了准备。第一场比赛，希望有更多球员可以出场，给他们机会，因为训练中他们用自己的表现告诉我已经准备好了。…"
