    "content": "联合国秘书长古特雷斯完成了自己最后一次联大开幕演讲。 当地时间2026年9月22日，美国纽约，联合国秘书长古特雷斯在联合国总部出席第81届联合国大会。视觉中国 图 据新华社报道，第81届联合国大会一般性辩论9月22日在纽约联合国总部开幕。联合国秘书长古特雷斯在开幕前的致辞中称，世界正在走向多极化，这一趋势不可逆转，多极化有不同呈现形式。 古特雷斯还指出，当前全球地缘政治分歧加深，不平等加剧，气候危机和人工智能带来的挑战不断上升，世界的“断层正在扩大”。 古特雷斯于2017年起担任联合国秘书长，定于今年底卸任。在古特…"
