    "content": "新华社北京9月23日电（记者冀泽、张泽钰）国务院台办发言人朱凤莲23日在例行新闻发布会上指出，世界上只有一个中国，台湾是中国的一部分。两岸应共同维护国家领土主权和海洋权益，维护中华民族的整体和根本利益。民进党当局对日本、菲律宾宣布启动台湾岛以东海域划界谈判的侵权行径装聋作哑，不但不尽力保护岛内民众利益，反而助纣为虐，增大台湾渔民权益受损的风险，丧失民族立场，令人不齿。 有记者问：台媒报道，台湾退役海巡舰“援赠”菲律宾，近日被发现已转成菲律宾籍执法船。台海巡部门称，“此案是援例办理”，台湾与菲律宾等签署渔业协议并建立…"
