    "content": "&nbsp; 数据显示，中国拥有规模超过2亿的独生子女群体[1]。 粗略算来，每7个中国人中，就有1个是独生子女。 对这2亿人来说，成年却始终没有一条清晰的分界线。读书、工作、结婚生子，人生不断向前，父母却从未真正从他们的生活中退场。 如今，最早一批独生子女的父母正在步入老年。一种新的处境随之出现： 父母的托举尚未结束，子女的养老责任却已经开始。 给父母养老，已经从一个遥远的概念，变成独生子女们不得不面对的现实。 当家庭的支持开始双向流动，这份延续多年的互相付出，究竟带来了更多安全感，还是让压力变得更加集中？ 近日…"
