    "content": "新华社北京9月23日电（记者 樊曦）记者从中国铁路北京局集团有限公司获悉，23日，经过400多名中铁十一局建设者连续9小时奋战，石雄铁路引入石济客专石家庄东站的关键连接设备42号道岔插铺完毕，在建石雄铁路与既有石济客专成功“牵手”，实现互联互通，为石雄铁路按期建成通车奠定坚实基础。 据中铁十一局项目总工程师刘爱军介绍，本次插铺的42号道岔是我国目前铁路插铺型号最大、长度最长的有砟高速道岔，全长157.2米，总重量达247吨，可大幅提高列车通过速度，缩短转线时间。施工中，建设者应用智能横移装置等先进设备，在列车暂时不…"
