    "description": "36氪获悉，锦江在线公告，上海市宝山区土地储备中心拟对公司下属控股子公司上海吴淞罗吉冷藏有限公司位于安达路241号范围内国有土地及地上建筑物等实施收购储备，拟收储价格合计6.68亿元。经公司初步测算，本次交易完成后预计对公司2026年及未来年度的税前利润影响约为5.19亿元。",
