    "content": "方法很简单 muse 自带了 tailscale 的连接器，直接页面上 设置 - 连接器 就可以连上 然后本来想让 muse 自建 ssh 服务，但是连不上，可能是因为沙盒的原因 只能反向隧道，我在 tailscale 本身就有几台小主机，然后随便找一台，开 sshd ，把鉴权信息告诉 muse ，它会帮你搞定后面的流程，然后在那台机器上 ssh localhost:port 就反向连到了 muse 的 linux 简单测试了一下： 8G 内存，2 核 2 线程，访问谷歌正常，就是这种反向隧道方式延迟有点大 后面想…"
