    "feed_name": "V2EX",
    "category": "论坛",
    "title": "[Apple] 小红书真恶心，已向 Apple Store 举报",
    "link": "https://www.v2ex.com/t/1244291#reply18",
    "pub_date": "2026-09-23 16:16:12",
