    "description": "上滑退不出，和拼多多一样，要两次才能退出。 小红书在普通内容浏览、图文详情、评论区等非游戏、非全屏沉浸式场景中启用了延迟系统手势，导致用户从屏幕底部上滑时，第一次操作无法返回主屏幕，必须再次上滑才能退出 App 。 该功能通常用于防止全屏游戏或沉浸式应用发生误触，但小红书的常规浏览页面没有明显的防误触需求，也未向用户提供关闭选项。这增加了退出 App 的操作成本，容易使用户误以为系统手势失效，并妨碍用户正常离开应用。 请审核小红书在这些…",
