    "content": "新华社加拉加斯9月22日电（记者田睿）委内瑞拉代总统德尔西·罗德里格斯22日在社交媒体上发文说，她已结束同美国总统特朗普的会晤。 罗德里格斯说，双方讨论了加强双边关系，以及在能源、矿业、安全等战略领域和其他共同关心议题上推进合作等事宜。 此次会晤发生在于美国纽约举行的第81届联合国大会一般性辩论期间。当天早些时候，委内瑞拉通讯社援引美国白宫发布的日程安排报道说，会晤以闭门形式进行。 由于美国持续干涉委内瑞拉内政，委内瑞拉于2019年1月与美国断绝外交关系。今年1月3日，美军对委内瑞拉发动大规模军事打击，强行控制委总…"
