    "description": "与传统堂食餐饮不同，无堂食外卖商家主要依托线上平台接单，消费者难以通过堂食环境直接了解经营场所和后厨情况，形成了监管的“隐蔽地带”。为此，广东省市场监管局分类打造政府示范街区、政企共建集聚区、平台集约厨房三类集中经营载体，形成可复制推广的网络餐饮治理路径。",
