    "content": "Dropbox 已将 Riviera \" 从一个文件预览服务演进为一个通用内容处理平台，支持超过 300 种文件格式和 100 多种转换能力。该平台现在每秒执行数十万次转换，并支持 Search、Replay、Sign 和 Dash，让 AI 工作负载能够复用为早期产品开发的内容处理基础设施。 Riviera 最初是 Dropbox 内部用于跨文件格式生成预览的服务。工程师们没有为单个格式和输出创建单独的处理服务，而是将内容处理分解为可复用的转换单元。例如，PowerPoint 预览可以通过将演示文稿转换为 PDF…"
